// One item per attachment, each with its file in the "data" field,
// so the dosya.dev step uploads every attachment of every email.
const out = [];
for (const item of $input.all()) {
  for (const [field, file] of Object.entries(item.binary ?? {})) {
    out.push({
      json: {
        email_subject: item.json.subject ?? "",
        email_from: item.json.from?.text ?? "",
        attachment_field: field,
      },
      binary: { data: file },
    });
  }
}
return out;
